from concurrent.futures import ThreadPoolExecutor

start='20260301'
end='20260509'


def q_price():
    return 'price', FinDatabase('股票','中国稀土','开盘价，最高价，最低价，收盘价，成交量，成交额，涨跌幅', start, end)

