    # 资金流向指标命名可能存在差异，先用常见口径尝试
    return 'fund', FinDatabase('股票','中国稀土','主力净流入，超大单净流入，大单净流入', start, end)

def q_sector():
    # 尝试获取稀土相关指数/板块近况（若返回None，后续用板块个股涨跌做替代）
